const rows = $input.all();

const today = new Date(
  new Date().toLocaleString("en-US", {
    timeZone: "Asia/Kolkata"
  })
);

today.setHours(0, 0, 0, 0);

const upcomingHolidays = [];

for (const item of rows) {
  const data = item.json;

  // Read holiday details
  const holidayName = data["Holiday Name"];
  const holidayDate = data["Holiday Date"];
  const notifyDays = Number(data["Notify Days Before"] || 3);

  // Skip incomplete records
  if (!holidayName || !holidayDate) continue;

  // Skip already sent notifications
  if (
    String(data["Notification Status"] || "").toLowerCase() === "sent"
  ) continue;

  // Parse holiday date
  const date = new Date(holidayDate);

  if (isNaN(date.getTime())) continue;

  date.setHours(0, 0, 0, 0);

  // Calculate days remaining
  const daysLeft = Math.round(
    (date - today) / (1000 * 60 * 60 * 24)
  );

  // Select holidays matching notification days
  if (daysLeft === notifyDays) {
    upcomingHolidays.push({
      name: holidayName,
      date: date.toLocaleDateString("en-IN"),
      daysLeft
    });
  }
}

// Prepare one combined notification
const hasHoliday = upcomingHolidays.length > 0;

const holidayList = upcomingHolidays.map(holiday => `
  <tr>
    <td style="padding:12px;border:1px solid #ddd;">
      ${holiday.name}
    </td>
    <td style="padding:12px;border:1px solid #ddd;">
      ${holiday.date}
    </td>
    <td style="padding:12px;border:1px solid #ddd;">
      ${holiday.daysLeft} days
    </td>
  </tr>
`).join("");

const holidayNames = upcomingHolidays
  .map(h => h.name)
  .join(", ");

return [{
  json: {
    hasHoliday,
    holidayCount: upcomingHolidays.length,
    holidayNames,
    emailSubject: `Upcoming Office Holiday Reminder - ${holidayNames}`,
    emailBody: `
      <div style="font-family:Arial,sans-serif;max-width:650px;margin:auto;color:#333;">
        <div style="background:#1f4e78;padding:22px;text-align:center;color:white;">
          <h2 style="margin:0;">Office Holiday Announcement</h2>
        </div>

        <div style="padding:25px;">
          <p>Dear Team,</p>

          <p>
            This is a friendly reminder about the upcoming
            office holiday(s). Please find the details below:
          </p>

          <table style="width:100%;border-collapse:collapse;text-align:left;">
            <tr style="background:#f0f3f6;">
              <th style="padding:12px;border:1px solid #ddd;">Holiday</th>
              <th style="padding:12px;border:1px solid #ddd;">Date</th>
              <th style="padding:12px;border:1px solid #ddd;">Remaining</th>
            </tr>
            ${holidayList}
          </table>

          <p style="margin-top:22px;">
            Please plan your work accordingly and complete any
            important tasks before the holiday.
          </p>

          <p>Wishing you a wonderful holiday!</p>

          <p>
            Regards,<br>
            <strong>HR Department</strong>
          </p>
        </div>

        <div style="background:#f0f3f6;padding:12px;text-align:center;font-size:12px;color:#777;">
          Automated notification from Office Holiday Notifier
        </div>
      </div>
    `
  }
}];
